/*
 * A210602  Triangle of coefficients of polynomials v(n,x) jointly generated
 *          with A210597; see the Formula section.
 * https://oeis.org/A210602
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) = flattened coefficients of the polynomials v(n,x) *
 *            generated by * u(1,x)=1, v(1,x)=1 *
 *            u(n,x)=2x*u(n-1,x)+v(n-1,x)+1 * v(n,x)=(x+1)*u(n-1,x)+v(n-1,x)+1
 *            * The sequence lists the coefficients of v(n,x) for each n,
 *            beginning * with the constant term, row by row
 * Range:     u8 n <= 24, u16 n <= 54, u32 n <= 54, u64 n <= 54, u128 n <= 54,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* Find the row r that contains the n‑th element. */
    idx_t r = 0;
    while (((r + 1) * (r + 2)) / 2 < n) /* use (r+1)*(r+2)/2 to avoid overflow for r=0 */
        ++r;
    /* Actually we need (r*(r+1))/2 >= n, so adjust: */
    while ((r * (r + 1)) / 2 < n)
        ++r;

    /* Position inside the row (0‑based). */
    idx_t prev_total = (r * (r - 1)) / 2;
    idx_t pos        = n - prev_total;      /* 1‑based inside the row */
    idx_t k          = pos - 1;              /* coefficient index */

    /* Allocate arrays for two consecutive rows. */
    seq_t *A_cur   = (seq_t *)malloc(r * sizeof(seq_t));
    seq_t *B_cur   = (seq_t *)malloc(r * sizeof(seq_t));
    seq_t *A_next  = (seq_t *)malloc(r * sizeof(seq_t));
    seq_t *B_next  = (seq_t *)malloc(r * sizeof(seq_t));

    /* Initial row (n = 1). */
    A_cur[0] = 1;
    B_cur[0] = 1;
    idx_t cur_len = 1;

    seq_t two = (seq_t)2;

    /* Build rows up to r. */
    for (idx_t row = 2; row <= r; ++row) {
        idx_t next_len = row;
        for (idx_t j = 0; j < next_len; ++j) {
            seq_t a_prev_k_minus_1 = (j == 0) ? (seq_t)0 : A_cur[j - 1];
            seq_t a_prev_k         = (j < cur_len) ? A_cur[j] : (seq_t)0;
            seq_t b_prev_k         = (j < cur_len) ? B_cur[j] : (seq_t)0;

            /* u(row,x) coefficients */
            A_next[j] = two * a_prev_k_minus_1 + b_prev_k;
            if (j == 0)
                A_next[j] = A_next[j] + 1; /* +1 for the constant term */

            /* v(row,x) coefficients */
            B_next[j] = a_prev_k_minus_1 + a_prev_k + b_prev_k;
            if (j == 0)
                B_next[j] = B_next[j] + 1; /* +1 for the constant term */
        }

        /* Prepare for the next iteration. */
        seq_t *tmp = A_cur; A_cur = A_next; A_next = tmp;
        tmp        = B_cur; B_cur = B_next; B_next = tmp;

        cur_len = next_len;
    }

    seq_t result = B_cur[k];

    /* Clean up. */
    free(A_cur);
    free(B_cur);
    free(A_next);
    free(B_next);

    return result;
}
